#pragma once
#include <stdint.h>

#include "Canvas.h"

// Weather icons, 1-bit, drawn from XBM arrays. The art is generated by scripts/dev/make_icons.py
// into IconsData.cpp; see assets/icons/README.md.
enum class Icon : uint8_t {
  ClearDay,
  ClearNight,
  PartlyCloudyDay,
  PartlyCloudyNight,
  Cloudy,
  Fog,
  Drizzle,
  Rain,
  Snow,
  Thunder,
  Unknown,
};
constexpr uint8_t ICON_COUNT = 11;

enum class IconSize : uint8_t { S24 = 24, S48 = 48 };

namespace draw {
// Draws the icon with its top-left corner at (x, y), black on whatever is underneath
// (white pixels of the icon are transparent). Does not change the draw colour.
void icon(Canvas& canvas, Icon icon, int x, int y, IconSize size);
}  // namespace draw

// WMO weather interpretation code (as used by Open-Meteo) to an icon. Codes with no icon of
// their own map to Unknown; isDay picks the day or night variant where one exists.
Icon iconForWmo(uint8_t wmoCode, bool isDay);

namespace icons {
// XBM data (row-major, LSB first, rows padded to whole bytes) for the icon at a size.
const uint8_t* bits(Icon icon, IconSize size);
}  // namespace icons
